use std::alloc::{GlobalAlloc,Layout,System};use std::sync::atomic::{AtomicUsize,Ordering};use ingetrazo_core::mesh::Mesh;use glam::DVec3;
static FAIL:AtomicUsize=AtomicUsize::new(0);struct Fault;unsafe impl GlobalAlloc for Fault{unsafe fn alloc(&self,l:Layout)->*mut u8{if FAIL.fetch_update(Ordering::SeqCst,Ordering::SeqCst,|n|if n>0{Some(n-1)}else{None}).ok()==Some(1){std::ptr::null_mut()}else{System.alloc(l)}}unsafe fn dealloc(&self,p:*mut u8,l:Layout){System.dealloc(p,l)}unsafe fn realloc(&self,p:*mut u8,l:Layout,n:usize)->*mut u8{if FAIL.fetch_update(Ordering::SeqCst,Ordering::SeqCst,|n|if n>0{Some(n-1)}else{None}).ok()==Some(1){std::ptr::null_mut()}else{System.realloc(p,l,n)}}}#[global_allocator]static ALLOC:Fault=Fault;
fn main(){for failure in 1..=4{let mut m=Mesh::new();m.add_vertex(DVec3::ZERO);let before=m.clone();let points=[DVec3::X,DVec3::Y,DVec3::Z];FAIL.store(failure,Ordering::SeqCst);let error=m.prepare_spatial_append(&points).err().expect("injected allocation must refuse");assert!(error.contains("refused"));assert_eq!(FAIL.load(Ordering::SeqCst),0);assert_eq!(m,before);assert_eq!(m.add_vertex(DVec3::ZERO),0);let patch=m.prepare_spatial_append(&points).unwrap();for point in points{m.vertices.push(ingetrazo_core::mesh::MeshVertex::new(point));}m.install_spatial_append(&patch).unwrap();m.restore_spatial_append(&patch).unwrap();m.vertices.truncate(1);assert_eq!(m,before);}println!("four actual allocator refusals before publication; unchanged mesh/index; retry+restore PASS");}
